sealed class NodeException(message: String): kotlin.Exception(message) {
        
        class InvalidSecretKey(message: String) : NodeException(message)
        
        class Bind(message: String) : NodeException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<NodeException> {
        override fun lift(error_buf: RustBuffer.ByValue): NodeException = FfiConverterTypeNodeError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeNodeError : FfiConverterRustBuffer<NodeException> {
    override fun read(buf: ByteBuffer): NodeException {
        
            return when(buf.getInt()) {
            1 -> NodeException.InvalidSecretKey(FfiConverterString.read(buf))
            2 -> NodeException.Bind(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: NodeException): ULong {
        return 4UL
    }

    override fun write(value: NodeException, buf: ByteBuffer) {
        when(value) {
            is NodeException.InvalidSecretKey -> {
                buf.putInt(1)
                Unit
            }
            is NodeException.Bind -> {
                buf.putInt(2)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



sealed class Request {
    
    data class Pair(
        val `hostName`: kotlin.String) : Request()
        
    {
        

        companion object
    }
    
    object ListKeys : Request()
    
    
    data class Sign(
        val `keyId`: kotlin.String, 
        val `data`: kotlin.ByteArray) : Request()
        
    {
        

        companion object
    }
    
    data class Ecdh(
        val `keyId`: kotlin.String, 
        val `peerPublicKey`: kotlin.ByteArray, 
        val `description`: kotlin.String?) : Request()
        
    {
        

        companion object
    }
    
    object PushEndpoint : Request()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRequest : FfiConverterRustBuffer<Request>{
    override fun read(buf: ByteBuffer): Request {
        return when(buf.getInt()) {
            1 -> Request.Pair(
                FfiConverterString.read(buf),
                )
            2 -> Request.ListKeys
            3 -> Request.Sign(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            4 -> Request.Ecdh(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            5 -> Request.PushEndpoint
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Request): ULong = when(value) {
        is Request.Pair -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`hostName`)
            )
        }
        is Request.ListKeys -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Request.Sign -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`keyId`)
                + FfiConverterByteArray.allocationSize(value.`data`)
            )
        }
        is Request.Ecdh -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`keyId`)
                + FfiConverterByteArray.allocationSize(value.`peerPublicKey`)
                + FfiConverterOptionalString.allocationSize(value.`description`)
            )
        }
        is Request.PushEndpoint -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: Request, buf: ByteBuffer) {
        when(value) {
            is Request.Pair -> {
                buf.putInt(1)
                FfiConverterString.write(value.`hostName`, buf)
                Unit
            }
            is Request.ListKeys -> {
                buf.putInt(2)
                Unit
            }
            is Request.Sign -> {
                buf.putInt(3)
                FfiConverterString.write(value.`keyId`, buf)
                FfiConverterByteArray.write(value.`data`, buf)
                Unit
            }
            is Request.Ecdh -> {
                buf.putInt(4)
                FfiConverterString.write(value.`keyId`, buf)
                FfiConverterByteArray.write(value.`peerPublicKey`, buf)
                FfiConverterOptionalString.write(value.`description`, buf)
                Unit
            }
            is Request.PushEndpoint -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





