/**
 * @suppress
 */
public object FfiConverterTypeResponse : FfiConverterRustBuffer<Response>{
    override fun read(buf: ByteBuffer): Response {
        return when(buf.getInt()) {
            1 -> Response.Paired(
                FfiConverterOptionalString.read(buf),
                )
            2 -> Response.Keys(
                FfiConverterSequenceTypeKeyInfo.read(buf),
                )
            3 -> Response.Signature(
                FfiConverterByteArray.read(buf),
                )
            4 -> Response.SharedSecret(
                FfiConverterByteArray.read(buf),
                )
            5 -> Response.Denied
            6 -> Response.UnknownKey
            7 -> Response.Error(
                FfiConverterString.read(buf),
                )
            8 -> Response.PushEndpoint(
                FfiConverterOptionalString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Response): ULong = when(value) {
        is Response.Paired -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`pushEndpoint`)
            )
        }
        is Response.Keys -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeKeyInfo.allocationSize(value.`keys`)
            )
        }
        is Response.Signature -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`der`)
            )
        }
        is Response.SharedSecret -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`secret`)
            )
        }
        is Response.Denied -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Response.UnknownKey -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Response.Error -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
        is Response.PushEndpoint -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`endpoint`)
            )
        }
    }

    override fun write(value: Response, buf: ByteBuffer) {
        when(value) {
            is Response.Paired -> {
                buf.putInt(1)
                FfiConverterOptionalString.write(value.`pushEndpoint`, buf)
                Unit
            }
            is Response.Keys -> {
                buf.putInt(2)
                FfiConverterSequenceTypeKeyInfo.write(value.`keys`, buf)
                Unit
            }
            is Response.Signature -> {
                buf.putInt(3)
                FfiConverterByteArray.write(value.`der`, buf)
                Unit
            }
            is Response.SharedSecret -> {
                buf.putInt(4)
                FfiConverterByteArray.write(value.`secret`, buf)
                Unit
            }
            is Response.Denied -> {
                buf.putInt(5)
                Unit
            }
            is Response.UnknownKey -> {
                buf.putInt(6)
                Unit
            }
            is Response.Error -> {
                buf.putInt(7)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is Response.PushEndpoint -> {
                buf.putInt(8)
                FfiConverterOptionalString.write(value.`endpoint`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Implemented by the app. `handle` is invoked on a blocking thread and may
 * take as long as the biometric prompt needs; requests are handled
 * concurrently, so the implementation must serialise UI itself.
 */
public interface Handler {
    
    fun `handle`(`peerId`: kotlin.String, `request`: Request): Response
    
    companion object
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceHandler {
    internal object `handle`: UniffiCallbackInterfaceHandlerMethod0 {
        override fun callback(`uniffiHandle`: Long,`peerId`: RustBuffer.ByValue,`request`: RustBuffer.ByValue,`uniffiOutReturn`: RustBuffer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeHandler.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`handle`(
                    FfiConverterString.lift(`peerId`),
                    FfiConverterTypeRequest.lift(`request`),
                )
            }
            val writeReturn = { value: Response -> uniffiOutReturn.setValue(FfiConverterTypeResponse.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeHandler.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeHandler.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceHandler.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `handle`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_phonetpm_mobile_fn_init_callback_vtable_handler(vtable)
    }
}

/**
 * The ffiConverter which transforms the Callbacks in to handles to pass to Rust.
 *
 * @suppress
 */
public object FfiConverterTypeHandler: FfiConverterCallbackInterface<Handler>()




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceTypeKeyInfo: FfiConverterRustBuffer<List<KeyInfo>> {
    override fun read(buf: ByteBuffer): List<KeyInfo> {
        val len = buf.getInt()
        return List<KeyInfo>(len) {
            FfiConverterTypeKeyInfo.read(buf)
        }
    }

    override fun allocationSize(value: List<KeyInfo>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeKeyInfo.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<KeyInfo>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeKeyInfo.write(it, buf)
        }
    }
}
